1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * Single source of truth for an owner's derived {@code checkDigit} — a single Luhn check digit
7	 * (0-9) computed over the digits contained in the owner's {@code customerCode}. Non-digit
8	 * characters in the customer code (the separating hyphens) are skipped; the standard Luhn
9	 * algorithm doubles every second digit from the right, subtracting 9 when a doubled value exceeds
10	 * 9, and the check digit is the amount needed to round the running sum up to the next multiple of
11	 * ten.
12	 *
13	 * <p>Derived at read time by the owner mapper from the already-stored {@code customerCode}, so it
14	 * needs no column of its own and can never drift from the code it checks.
15	 */
16	public final class OwnerCheckDigit {
17	
18	    private OwnerCheckDigit() {
19	    }
20	
21	    /** The Luhn check digit of an already-stored owner, read from its {@code customerCode}. */
22	    public static Integer checkDigit(Owner owner) {
23	        return luhn(owner.getCustomerCode());
24	    }
25	
26	    /** The Luhn check digit (0-9) over the digits contained in {@code s}; {@code null} when absent. */
27	    public static Integer luhn(String s) {
28	        if (s == null) {
29	            return null;
30	        }
31	        int sum = 0;
32	        boolean dbl = true;
33	        for (int i = s.length() - 1; i >= 0; i--) {
34	            char c = s.charAt(i);
35	            if (c < '0' || c > '9') {
36	                continue;
37	            }
38	            int d = c - '0';
39	            if (dbl) {
40	                d *= 2;
41	                if (d > 9) {
42	                    d -= 9;
43	                }
44	            }
45	            sum += d;
46	            dbl = !dbl;
47	        }
48	        return (10 - (sum % 10)) % 10;
49	    }
50	}
