1	package org.springframework.samples.petclinic.model;
2	
3	import java.util.Map;
4	
5	/**
6	 * Single source of truth for the fixed city-to-region table and the per-region postcode ranges.
7	 *
8	 * <p>This is a domain concept shared by the read-time {@code locality} derivation (see
9	 * {@code org.springframework.samples.petclinic.mapper.OwnerMapper}) and the create/update postcode
10	 * validation in the REST pipeline, so it lives in the business layer that both already depend on
11	 * rather than in either. A city not in the table has region {@link #UNKNOWN} and accepts any 4-digit
12	 * postcode.
13	 */
14	public final class OwnerRegion {
15	
16	    /** Region reported for a city that is not in the fixed table. */
17	    public static final String UNKNOWN = "UNKNOWN";
18	
19	    /** Fixed city-to-region table; any other city has region {@link #UNKNOWN}. */
20	    private static final Map<String, String> CITY_REGION = Map.of(
21	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
22	
23	    /** Region to inclusive 4-digit postcode range {@code {low, high}}. */
24	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
25	        "NSW", new int[] {2000, 2099},
26	        "VIC", new int[] {3000, 3099},
27	        "QLD", new int[] {4000, 4099});
28	
29	    private OwnerRegion() {
30	    }
31	
32	    /** The canonical region for {@code city}, or {@link #UNKNOWN} when the city is not in the table. */
33	    public static String regionOf(String city) {
34	        return CITY_REGION.getOrDefault(city, UNKNOWN);
35	    }
36	
37	    /**
38	     * The locality for an owner, preferring the postcode: when {@code postcode} is a 4-digit value
39	     * inside a known region's range that region wins, disambiguating cities that share a name.
40	     * Otherwise (postcode absent, malformed, or in no known range) this falls back to the
41	     * city-to-region table, which still returns {@link #UNKNOWN} for an unknown city.
42	     */
43	    public static String localityOf(String city, String postcode) {
44	        String byPostcode = regionForPostcode(postcode);
45	        return byPostcode != null ? byPostcode : regionOf(city);
46	    }
47	
48	    /** The region whose inclusive range contains {@code postcode}, or {@code null} when none does. */
49	    private static String regionForPostcode(String postcode) {
50	        if (postcode == null || !postcode.matches("\\d{4}")) {
51	            return null;
52	        }
53	        int value = Integer.parseInt(postcode);
54	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
55	            int[] range = entry.getValue();
56	            if (value >= range[0] && value <= range[1]) {
57	                return entry.getKey();
58	            }
59	        }
60	        return null;
61	    }
62	
63	    /**
64	     * Whether {@code postcode} is acceptable for {@code city}. A postcode must be exactly four
65	     * digits; a city whose region is known must additionally fall within that region's inclusive
66	     * range, while a city with no known region accepts any 4-digit postcode.
67	     */
68	    public static boolean isPostcodeValid(String city, String postcode) {
69	        if (postcode == null || !postcode.matches("\\d{4}")) {
70	            return false;
71	        }
72	        int[] range = REGION_POSTCODES.get(regionOf(city));
73	        if (range == null) {
74	            return true;
75	        }
76	        int value = Integer.parseInt(postcode);
77	        return value >= range[0] && value <= range[1];
78	    }
79	}
