1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	
6	/**
7	 * Single source of truth for an owner's derived {@code identityKey} — the one value that now
8	 * expresses all duplicate detection for the {@code POST /api/owners} pipeline. The key is
9	 * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}, where the telephone is
10	 * reduced to E.164 through {@link OwnerTelephone#toE164} and the email lower-cased through
11	 * {@link OwnerEmail#normalize}; a missing email or household id contributes an empty segment.
12	 *
13	 * <p>Two owners are duplicates only when their <em>whole</em> identity keys are equal. Because the
14	 * telephone is part of the key, two members of the same household (same {@code householdId}) with
15	 * different telephones have different keys and are both allowed — only an exact full-key match is a
16	 * duplicate. Used by {@link CheckOwnerIdentityUnique} to reject a collision and by the owner mapper
17	 * to return the key on the owner.
18	 */
19	public final class OwnerIdentity {
20	
21	    private OwnerIdentity() {
22	    }
23	
24	    /**
25	     * Builds the identity key from its three raw parts: the submitted/stored telephone (normalized
26	     * to E.164 here), the email (lower-cased here) and the already-derived household id. Any part
27	     * that is {@code null} or cannot normalize contributes an empty segment.
28	     */
29	    public static String identityKey(String telephone, String email, String householdId) {
30	        String normalizedTelephone = OwnerTelephone.toE164(telephone);
31	        String normalizedEmail = OwnerEmail.normalize(email);
32	        return (normalizedTelephone == null ? "" : normalizedTelephone) + "|"
33	                + (normalizedEmail == null ? "" : normalizedEmail) + "|"
34	                + (householdId == null ? "" : householdId);
35	    }
36	
37	    /**
38	     * The identity key of an already-stored owner, read from its persisted fields. The single
39	     * {@code Owner}-to-key definition shared by {@link CheckOwnerIdentityUnique} and the owner
40	     * mapper, so the uniqueness check and the returned {@code identityKey} can never drift apart.
41	     */
42	    public static String identityKey(Owner owner) {
43	        return identityKey(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
44	    }
45	
46	    /**
47	     * The identity key a create request <em>would</em> produce. The household-id segment is derived
48	     * the same way {@link AssignOwnerHousehold} will later assign it: the stable
49	     * {@link OwnerHousehold#householdId} when the request opts in with {@code sharesHousehold: true},
50	     * otherwise empty.
51	     */
52	    static String forRequest(OwnerFieldsDto request) {
53	        String householdId = Boolean.TRUE.equals(request.getSharesHousehold())
54	                ? OwnerHousehold.householdId(request.getLastName(), request.getAddress())
55	                : "";
56	        return identityKey(request.getTelephone(), request.getEmail(), householdId);
57	    }
58	}
