1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Single source of truth for the owner-household identity rule. Two owners count as the same
12	 * household when their last names match (compared case-insensitively, whitespace collapsed) and
13	 * their addresses match in their normalized form (see {@link OwnerAddress#normalize}: whitespace
14	 * collapsed, upper-cased, common abbreviations expanded). This class owns both the comparison
15	 * ({@link #sameHousehold}, built on {@link #normalize}) and the derivation of the stable shared
16	 * {@link #householdId} that identifies a household.
17	 *
18	 * <p>Used by {@link AssignOwnerHousehold} to find the household's existing members and to compute
19	 * the id they share, and by {@link OwnerIdentity} to derive the household segment of an owner's
20	 * identity key — so the definition of "same household" lives here and nowhere else.
21	 */
22	final class OwnerHousehold {
23	
24	    private OwnerHousehold() {
25	    }
26	
27	    /**
28	     * Reduces a value to its comparison form: trimmed, inner runs of whitespace collapsed to a
29	     * single space, and lower-cased. A {@code null} value yields an empty string.
30	     */
31	    static String normalize(String value) {
32	        if (value == null) {
33	            return "";
34	        }
35	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
36	    }
37	
38	    /**
39	     * Tells whether an existing owner belongs to the household identified by the given last name and
40	     * address — the one place that defines what "same household" means. Last names are reduced
41	     * through {@link #normalize} and addresses through {@link OwnerAddress#normalize} before
42	     * comparison, so differently cased, spaced or abbreviated values that mean the same thing still
43	     * match.
44	     */
45	    static boolean sameHousehold(Owner existing, String lastName, String address) {
46	        return normalize(existing.getLastName()).equals(normalize(lastName))
47	                && OwnerAddress.normalize(existing.getAddress())
48	                        .equals(OwnerAddress.normalize(address));
49	    }
50	
51	    /**
52	     * Derives the stable household identifier shared by every owner in the same household. Two
53	     * owners whose normalized last name and address match produce the same value, so the id can be
54	     * computed independently for each joining owner without coordinating through the database. The
55	     * value is {@code "HH-"} followed by the first 12 upper-case hex characters of the SHA-256 of
56	     * the normalized {@code "<lastName>|<address>"}.
57	     */
58	    static String householdId(String lastName, String address) {
59	        String key = normalize(lastName) + "|" + OwnerAddress.normalize(address);
60	        try {
61	            byte[] digest = MessageDigest.getInstance("SHA-256")
62	                    .digest(key.getBytes(StandardCharsets.UTF_8));
63	            StringBuilder sb = new StringBuilder();
64	            for (int i = 0; i < 6; i++) {
65	                sb.append(String.format("%02X", digest[i]));
66	            }
67	            return "HH-" + sb;
68	        }
69	        catch (NoSuchAlgorithmException ex) {
70	            throw new IllegalStateException("SHA-256 not available", ex);
71	        }
72	    }
73	}
