1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	import org.springframework.samples.petclinic.repository.OwnerRepository;
5	
6	/**
7	 * Single source of truth for the "owners in a city" primitive, used wherever an owner is created.
8	 *
9	 * <p>Both the city-capacity check ({@link CheckOwnerCityCapacity}) and the per-city customer-code
10	 * sequence ({@link AssignOwnerCustomerCode}) depend on the same count, and are meant to stay
11	 * consistent, so the definition of what counts as "the same city" lives here rather than being
12	 * inlined in each. The city is matched exactly today; aligning it with the address/household
13	 * normalization would be a change in one place.
14	 */
15	final class OwnerCity {
16	
17	    private OwnerCity() {
18	    }
19	
20	    /** The number of existing owners whose city matches {@code city}. */
21	    static long countOwnersInCity(OwnerRepository ownerRepository, String city) {
22	        return ownerRepository.findAll().stream()
23	                .filter(existing -> city.equals(existing.getCity()))
24	                .count();
25	    }
26	}
