1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.mapstruct.Named;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.model.OwnerRegion;
10	import org.springframework.samples.petclinic.rest.function.owner.OwnerCheckDigit;
11	import org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity;
12	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
13	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
14	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
15	
16	import java.util.Collection;
17	import java.util.List;
18	
19	/**
20	 * Maps Owner & OwnerDto using Mapstruct
21	 */
22	@Mapper(uses = PetMapper.class)
23	public interface OwnerMapper {
24	
25	    @Mapping(target = "displayName", source = "owner", qualifiedByName = "displayName")
26	    @Mapping(target = "initials", source = "owner", qualifiedByName = "initials")
27	    @Mapping(target = "locality", source = "owner", qualifiedByName = "locality")
28	    @Mapping(target = "contactPreference", source = "owner", qualifiedByName = "contactPreference")
29	    @Mapping(target = "identityKey", source = "owner", qualifiedByName = "identityKey")
30	    @Mapping(target = "checkDigit", source = "owner", qualifiedByName = "checkDigit")
31	    OwnerDto toOwnerDto(Owner owner);
32	
33	    @Named("identityKey")
34	    default String identityKey(Owner owner) {
35	        return OwnerIdentity.identityKey(owner);
36	    }
37	
38	    @Named("checkDigit")
39	    default Integer checkDigit(Owner owner) {
40	        return OwnerCheckDigit.checkDigit(owner);
41	    }
42	
43	    @Named("displayName")
44	    default String displayName(Owner owner) {
45	        return owner.getLastName() + ", " + owner.getFirstName();
46	    }
47	
48	    @Named("initials")
49	    default String initials(Owner owner) {
50	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
51	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
52	    }
53	
54	    @Named("locality")
55	    default String locality(Owner owner) {
56	        return OwnerRegion.localityOf(owner.getCity(), owner.getPostcode());
57	    }
58	
59	    @Named("contactPreference")
60	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
61	        String email = owner.getEmail();
62	        return (email != null && !email.isBlank())
63	            ? OwnerDto.ContactPreferenceEnum.EMAIL
64	            : OwnerDto.ContactPreferenceEnum.PHONE;
65	    }
66	
67	    Owner toOwner(OwnerDto ownerDto);
68	
69	    @Mapping(target = "id", ignore = true)
70	    @Mapping(target = "pets", ignore = true)
71	    Owner toOwner(OwnerFieldsDto ownerDto);
72	
73	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
74	
75	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
76	
77	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
78	        OwnerPageDto ownerPageDto = new OwnerPageDto();
79	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
80	        ownerPageDto.setPage(ownerPage.getNumber());
81	        ownerPageDto.setSize(ownerPage.getSize());
82	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
83	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
84	        return ownerPageDto;
85	    }
86	}
