1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Out;
7	import org.springframework.samples.petclinic.model.OwnerRegion;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.web.bind.annotation.RequestBody;
10	
11	/**
12	 * Rejects a create request that is missing or blank in any required owner field.
13	 *
14	 * <p>Runs first in the {@code POST /api/owners} pipeline. It binds the body once (this is the only
15	 * step that reads {@code @RequestBody}) and republishes it for {@link BuildOwner}. Each of
16	 * firstName, lastName, address, city and telephone must be present and non-blank; any that are not
17	 * are collected and reported together via {@link OwnerFieldsInvalidException}.
18	 *
19	 * <p>The telephone is converted to E.164 form (see {@link OwnerTelephone#toE164}). The E.164 value
20	 * replaces the submitted one on the republished body, so it is what gets stored and returned. A
21	 * number that cannot form valid E.164 is rejected as an invalid {@code telephone}.
22	 */
23	public class ValidateOwnerFields {
24	
25	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
26	            throws OwnerFieldsInvalidException {
27	        List<String> errors = new ArrayList<>();
28	        if (isBlank(request.getFirstName())) {
29	            errors.add("firstName");
30	        }
31	        if (isBlank(request.getLastName())) {
32	            errors.add("lastName");
33	        }
34	        // The address is normalized (whitespace collapsed, upper-cased, abbreviations expanded)
35	        // before the required-field check, so an address that is blank only after normalization is
36	        // rejected; the normalized value replaces the submitted one, so it is what gets stored,
37	        // returned and compared for household identity.
38	        String address = OwnerAddress.normalize(request.getAddress());
39	        if (address.isEmpty()) {
40	            errors.add("address");
41	        }
42	        else {
43	            request.setAddress(address);
44	        }
45	        if (isBlank(request.getCity())) {
46	            errors.add("city");
47	        }
48	        if (isBlank(request.getTelephone())) {
49	            errors.add("telephone");
50	        }
51	        else {
52	            String telephone = OwnerTelephone.toE164(request.getTelephone());
53	            if (telephone == null) {
54	                errors.add("telephone");
55	            }
56	            else {
57	                request.setTelephone(telephone);
58	            }
59	        }
60	        // Email is optional. When present it must be syntactically valid; it is normalized to
61	        // lower case so it is stored and returned lower-cased.
62	        String email = request.getEmail();
63	        if (email != null) {
64	            if (!OwnerEmail.isValid(email)) {
65	                errors.add("email");
66	            }
67	            else {
68	                request.setEmail(OwnerEmail.normalize(email));
69	            }
70	        }
71	        // Postcode is optional. When present it must be exactly four digits and, for a city with a
72	        // known region, fall within that region's postcode range; a city with no known region
73	        // accepts any 4-digit postcode. An absent postcode leaves the owner backward-compatible.
74	        String postcode = request.getPostcode();
75	        if (postcode != null && !OwnerRegion.isPostcodeValid(request.getCity(), postcode)) {
76	            errors.add("postcode");
77	        }
78	        if (!errors.isEmpty()) {
79	            throw new OwnerFieldsInvalidException(errors);
80	        }
81	        validated.set(request);
82	    }
83	
84	    private static boolean isBlank(String value) {
85	        return value == null || value.isBlank();
86	    }
87	}
